import { Request, Response, NextFunction } from 'express';
import Joi from 'joi';
import { AppError } from '../types';

type ValidationSource = 'body' | 'query' | 'params';

/**
 * Validation middleware factory
 * @param schema - Joi validation schema
 * @param source - Where to validate from (body, query, params)
 */
export const validate = (
  schema: Joi.Schema,
  source: ValidationSource = 'body'
) => {
  return (req: Request, _res: Response, next: NextFunction) => {
    const { error, value } = schema.validate(req[source], {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      const errorMessages = error.details.map((detail) => detail.message).join(', ');
      throw new AppError({
        status: 400,
        code: 'VALIDATION_ERROR',
        message: errorMessages,
      });
    }

    // Replace req[source] with validated and sanitized value
    req[source] = value;
    next();
  };
};

import {
  ClientSession,
  FilterQuery,
  LeanDocument,
  QueryOptions,
  SaveOptions,
  UpdateQuery,
  Model,
} from 'mongoose';

interface FindOptions {
  limit?: number;
  skip?: number;
  select?: any;
  sort?: any;
}

export default class BaseRepository<T> {
  private model: Model<T>;

  constructor(model: Model<T>) {
    this.model = model;
  }

  get = async (id: string, session?: ClientSession): Promise<LeanDocument<T> | null> => {
    const query = this.model.findById(id);
    if (session) {
      query.session(session);
    }
    return query.lean();
  };

  findOne = async (query: FilterQuery<T>, session?: ClientSession): Promise<LeanDocument<T> | null> => {
    const dbQuery = this.model.findOne(query);
    if (session) {
      dbQuery.session(session);
    }
    return dbQuery.lean();
  };

  findById = async (_id: string, session?: ClientSession): Promise<LeanDocument<T> | null> => {
    const query = this.model.findById(_id);
    if (session) {
      query.session(session);
    }
    return query.lean();
  };

  findAll = async (
    filter: FilterQuery<T> = {},
    options: FindOptions = {}
  ): Promise<LeanDocument<T>[]> => {
    const query = this.model.find(filter);
    if (options.limit) query.limit(options.limit);
    if (options.skip) query.skip(options.skip);
    if (options.select) query.select(options.select);
    if (options.sort) query.sort(options.sort);
    return query.lean();
  };

  save = async (data: Partial<T>, options: SaveOptions = {}): Promise<LeanDocument<T>> => {
    const instance = new this.model(data);
    return (await instance.save(options)).toObject();
  };

  update = async (
    query: FilterQuery<T>,
    data: Partial<T> | UpdateQuery<T>,
    options: QueryOptions = { new: true }
  ): Promise<LeanDocument<T> | null> => {
    return this.model.findOneAndUpdate(query, data, options).lean();
  };

  delete = async (query: FilterQuery<T>, options: QueryOptions = {}): Promise<void> => {
    await this.model.deleteOne(query, options);
  };

  deleteMany = async (query: FilterQuery<T>, options: QueryOptions = {}): Promise<void> => {
    await this.model.deleteMany(query, options);
  };

  updateMany = async (
    query: FilterQuery<T>,
    data: Partial<T> | UpdateQuery<T>,
    options: QueryOptions = {}
  ): Promise<any> => {
    return await this.model.updateMany(query, data, options);
  };

  findMany = (filter: FilterQuery<T>, projection?: any) => {
    return this.model.find(filter, projection);
  };
}

import { Request, Response, NextFunction } from 'express';
import logger from '@/services/logger';

// For controller methods
export const catchAsync = (
  fn: (req: Request, res: Response, next: NextFunction) => Promise<any>
) => {
  return (req: Request, res: Response, next: NextFunction) => {
    fn(req, res, next).catch(next);
  };
};

// For functions
export const wrapAsync = <T extends (...args: any[]) => Promise<any>>(
  fn: T
): T => {
  return ((...args: any[]) => {
    return fn(...args).catch((err: any) => {
      // Centralized error handling
      logger.error(`Async error: ${err.message}`, { code: err.code });
      throw err;
    });
  }) as T;
};

/**
 * Convert YYYYMMDD format string to Date object
 * @param dateStr - Date string in YYYYMMDD format (e.g., "20250215")
 * @returns Date object
 */
export const yyyymmddToDate = (dateStr: string): Date => {
  if (!/^\d{8}$/.test(dateStr)) {
    throw new Error(`Invalid date format. Expected YYYYMMDD, got: ${dateStr}`);
  }

  const year = parseInt(dateStr.substring(0, 4), 10);
  const month = parseInt(dateStr.substring(4, 6), 10) - 1; // Month is 0-indexed
  const day = parseInt(dateStr.substring(6, 8), 10);

  return new Date(year, month, day);
};

/**
 * Convert Date object to YYYYMMDD format string
 * @param date - Date object
 * @returns Date string in YYYYMMDD format (e.g., "20250215")
 */
export const dateToYyyymmdd = (date: Date): string => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');

  return `${year}${month}${day}`;
};

/**
 * Get today's date in YYYYMMDD format
 * @returns Today's date in YYYYMMDD format
 */
export const getTodayYyyymmdd = (): string => {
  return dateToYyyymmdd(new Date());
};

/**
 * Add days to a YYYYMMDD date string
 * @param dateStr - Date string in YYYYMMDD format
 * @param days - Number of days to add
 * @returns Date string in YYYYMMDD format
 */
export const addDaysToYyyymmdd = (dateStr: string, days: number): string => {
  const date = yyyymmddToDate(dateStr);
  date.setDate(date.getDate() + days);
  return dateToYyyymmdd(date);
};

/**
 * Compare two YYYYMMDD date strings
 * @param date1 - First date in YYYYMMDD format
 * @param date2 - Second date in YYYYMMDD format
 * @returns Negative if date1 < date2, 0 if equal, positive if date1 > date2
 */
export const compareYyyymmdd = (date1: string, date2: string): number => {
  return date1.localeCompare(date2);
};

// Mongo duplicate-key errors (unique index violations). Single writes carry
// code 11000 directly; bulk writes (insertMany) nest them inside writeErrors.
export const isDuplicateKeyError = (error: unknown): boolean => {
  const err = error as { code?: unknown; writeErrors?: Array<{ code?: unknown }> };
  if (err?.code === 11000) {
    return true;
  }
  return Array.isArray(err?.writeErrors) && err.writeErrors.some((e) => e?.code === 11000);
};

export const buildContainsRegex = (value: string): { $regex: string; $options: 'i' } => ({
  $regex: value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'),
  $options: 'i',
});

