  private toStringArray(value: unknown): string[] | undefined {
    if (Array.isArray(value)) {
      const list = value
        .map((item) => String(item).trim())
        .filter(Boolean);
      return list.length ? list : undefined;
    }

    if (typeof value === 'string') {
      const list = value
        .split(',')
        .map((item) => item.trim())
        .filter(Boolean);
      return list.length ? list : undefined;
    }

    return undefined;
  }
}

import { model, Model, Schema } from 'mongoose';
import { IExternalBooking } from '@/modules/externalBookings/types';

const externalBookingSchema = new Schema<IExternalBooking>(
  {
    userId: {
      type: String,
      required: true,
      index: true,
    },
    dependentId: {
      type: String,
      index: true,
    },
    corporateId: {
      type: String,
      index: true,
    },
    integration: {
      type: String,
      enum: ['labstack', 'healthians'],
      required: true,
      index: true,
    },
    providerType: {
      type: String,
      required: true,
      trim: true,
      index: true,
    },
    appointmentType: {
      type: String,
      required: true,
      trim: true,
      index: true,
    },
    externalProviderId: {
      type: String,
      required: true,
      trim: true,
      index: true,
    },
    externalBookingId: {
      type: String,
      trim: true,
      index: true,
    },
    externalSlotRef: {
      type: String,
      trim: true,
    },
    meetingLink: {
      type: String,
