  private splitName(name: string): { firstName: string; lastName?: string } {
    const parts = (name || '').trim().split(/\s+/).filter(Boolean);
    if (parts.length === 0) {
      return { firstName: 'Patient' };
    }
    if (parts.length === 1) {
      return { firstName: parts[0] };
    }

    return {
      firstName: parts[0],
      lastName: parts.slice(1).join(' '),
    };
  }

  private getFirstString(
    source: Record<string, unknown>,
    keys: string[]
  ): string | undefined {
    for (const key of keys) {
      const value = source[key];
      if (typeof value === 'string' && value.trim()) {
        return value.trim();
      }
      if (typeof value === 'number') {
        return String(value);
      }
    }

    return undefined;
  }

  private getFirstNumber(
    source: Record<string, unknown>,
    keys: string[]
  ): number | undefined {
    for (const key of keys) {
      const value = source[key];
      if (typeof value === 'number') {
        return value;
      }
      if (typeof value === 'string' && value.trim()) {
        const parsed = Number(value);
        if (!Number.isNaN(parsed)) {
          return parsed;
        }
      }
    }

    return undefined;
  }

  private getStringArray(
    source: Record<string, unknown>,
    keys: string[]
  ): string[] | undefined {
    for (const key of keys) {
      const value = source[key];
      if (Array.isArray(value)) {
        const mapped = value
          .map((item) => (typeof item === 'string' ? item.trim() : undefined))
          .filter((item): item is string => Boolean(item));
        return mapped.length ? mapped : undefined;
      }
      if (typeof value === 'string' && value.trim()) {
        const parts = value
          .split(',')
          .map((item) => item.trim())
          .filter(Boolean);
        return parts.length ? parts : undefined;
      }
    }

    return undefined;
  }

  private fallbackId(source: Record<string, unknown>): string {
    return `ls-${Buffer.from(JSON.stringify(source)).toString('base64').slice(0, 12)}`;
