                medicine.instructions
                  ? `Instructions: ${this.escapeHtml(medicine.instructions)}`
                  : '',
                medicine.duration
                  ? `Duration: ${this.escapeHtml(medicine.duration)}`
                  : '',
              ]
                .filter(Boolean)
                .join('<br />');

              return `
                <div class="medicine">
